inline ftxui::Element render_ascii_art() {
    using namespace ftxui;
    std::vector<Element> rows;
    // Process 2 pixels vertically for every character row
    for (int y = 0; y < ASCII_HEIGHT; y += 2) {
        std::vector<Element> cols;
        for (int x = 0; x < ASCII_WIDTH; ++x) {
            uint8_t r1 = ascii_img[y][x][0];
            uint8_t g1 = ascii_img[y][x][1];
            uint8_t b1 = ascii_img[y][x][2];
            uint8_t a1 = ascii_img[y][x][3];
            
            uint8_t r2 = ascii_img[y+1][x][0];
            uint8_t g2 = ascii_img[y+1][x][1];
            uint8_t b2 = ascii_img[y+1][x][2];
            uint8_t a2 = ascii_img[y+1][x][3];
            
            if (a1 == 0 && a2 == 0) {
                cols.push_back(text(" "));
            } else if (a1 == 0 && a2 != 0) {
                cols.push_back(text("▄") | color(Color::RGB(r2, g2, b2)));
            } else if (a1 != 0 && a2 == 0) {
                cols.push_back(text("▀") | color(Color::RGB(r1, g1, b1)));
            } else {
                cols.push_back(text("▀") | color(Color::RGB(r1, g1, b1)) | bgcolor(Color::RGB(r2, g2, b2)));
            }
        }
        rows.push_back(hbox(std::move(cols)) | center);
    }
    return vbox(std::move(rows)) | center;
}
